/// <summary>
/// MPJ_2677 - Kscerri - 10/06/2021
/// The <t>PurchReqTable</t> table extension
/// </summary>
[ExtensionOf(tableStr(PurchReqTable))]
final class METPurchReqTable_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// Find by purchreqId
    /// </summary>
    /// <param name = "_purchReqId">purchreqid</param>
    /// <returns>purchReqTable</returns>
    public static PurchReqTable findByPurchReqId(PurchReqId _purchReqId)
    {
        PurchReqTable purchReqTable;

        select firstonly purchReqTable
            where purchReqTable.PurchReqId == _purchReqId;

        return purchReqTable;
    }

    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// get customer name
    /// </summary>
    /// <param name = "_custAccount">customer account</param>
    /// <returns>name</returns>
    public Name getCustName(CustAccount _custAccount)
    {
        CustTable custTable;
        DirPartyTable dirPartyTable;

        custTable = custTable::find(_custAccount);

        select firstonly name from dirPartyTable 
            where dirPartyTable.RecId == custTable.Party;

        return dirPartyTable.Name;
    }

    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// gets cust name on insert
    /// </summary>
    public void insert()
    {
        next insert();

        this.METCustName = this.getCustName(this.METCustAcc);
    }

    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// updates cust name on update
    /// </summary>
    public void update()
    {
        if (!this.METCustAcc)
        {
            this.METCustName = null;
        }
        else
        {
            this.METCustName = this.getCustName(this.METCustAcc);
        }

        next update();
    }
